<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT l.*,p.nome paciente_nome,p.cpf paciente_cpf FROM laudos l JOIN pacientes p ON p.id=l.paciente_id WHERE l.id=? AND l.medico_id=?');$s->execute([$id,$m['id']]);$l=$s->fetch();if(!$l)exit('Laudo não encontrado.');$body=trim((string)$l['conteudo_personalizado']);if($body==='')$body='<h3>Identificação</h3><p><b>Paciente:</b> '.e($l['paciente_nome']).'</p><h3>História clínica</h3><p>'.nl2br(e($l['historico_clinico'])).'</p><h3>Avaliação / exame físico</h3><p>'.nl2br(e($l['avaliacao'])).'</p>'.($l['exames']?'<h3>Exames</h3><p>'.nl2br(e($l['exames'])).'</p>':'').'<h3>Diagnóstico</h3><p><b>CID-10:</b> '.e($l['cid_codigo']).' — '.e($l['cid_descricao']).'</p>'.($l['repercussao']?'<h3>Repercussão funcional</h3><p>'.nl2br(e($l['repercussao'])).'</p>':'').'<h3>Conclusão</h3><p>'.nl2br(e($l['conclusao'])).'</p>';else$body=nl2br(e($body));?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title><?=e($l['titulo'])?></title><style>body{font:14px Arial;max-width:820px;margin:30px auto;line-height:1.6}.doc{border:1px solid #ddd;padding:45px;min-height:950px}.sign{text-align:center;margin-top:70px}.meta{font-size:12px;color:#666}@media print{.no-print{display:none}body{margin:0}.doc{border:0}}</style></head><body><div class="no-print"><button onclick="print()">Imprimir / Salvar PDF</button></div><article class="doc"><h1 style="text-align:center"><?=e($l['titulo']?:'LAUDO MÉDICO')?></h1><?=$body?><p><?=date('d/m/Y',strtotime($l['data_emissao']))?></p><div class="sign"><?php if(!empty($m['assinatura_path'])&&file_exists(__DIR__.'/../'.$m['assinatura_path'])):?><img src="/medical/<?=e($m['assinatura_path'])?>" style="max-width:220px;max-height:90px"><br><?php endif;?><b><?=e($m['nome_completo'])?></b><br>CRM <?=e($m['crm'].'/'.$m['uf'])?></div><hr><div class="meta">Código: <?=e($l['codigo_validacao'])?><br>Validação: https://<?=e($_SERVER['HTTP_HOST'])?>/medical/validar.php?id=<?=e($l['codigo_validacao'])?></div></article></body></html>